window.kbPageData["views/entry/k-92052a1e0611bc45"] = {"key":"entry/k-92052a1e0611bc45","state":{"route":"entry/k-92052a1e0611bc45"},"node":{"id":"k-92052a1e0611bc45","mode":"k","title":"优化营商环境","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":["营造国际化法治化便利化营商环境"],"qs":["江苏 2024 B类 行测#2"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"政府应当坚持市场化、法治化、国际化原则优化营商环境，完善法治保障和政务服务，便利市场主体投资兴业。","review":{"definition":"政府应当坚持市场化、法治化、国际化原则优化营商环境，完善法治保障和政务服务，便利市场主体投资兴业。","explanation":"二十届中央深改委第二次会议把全面优化营商环境、完善服务保障体系列为建设开放型经济新体制的举措，支持本题③的方向。国务院条例把市场化、法治化、国际化列为原则，把跨境贸易便利化落实到简化通关等措施。海南自贸港建设的地方行动计划则直接把法治化、国际化、便利化同时用于描述营商环境，③可按这一有政策实例的举措理解。","references":[{"source":"web-12f5279a55922f7e","location":"建设更高水平开放型经济新体制相关段落","quote":"全面优化营商环境，完善服务保障体系"},{"source":"web-8c0843154f49006b","location":"第四条、第四十五条","quote":"促进跨境贸易便利化"},{"source":"web-3b9e64a0cdbc3943","location":"行动计划导语","quote":"法治化、国际化、便利化营商环境"}],"evidence":"营造国际化法治化便利化营商环境","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 B类 行测#2":{"paper":"江苏 2024 B类 行测","n":2,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",1],"asrc":["8dd171daee6fc74e9718.pdf",1],"card":"b394a29760ed0577e9e55260","links":[{"id":"k-92052a1e0611bc45","role":"直接考查","why":"优化营商环境和完善服务保障是建设开放型经济新体制的配套举措。"}]}},"terms":{},"references":{"web-12f5279a55922f7e":{"name":"新华社《习近平主持召开中央全面深化改革委员会第二次会议》","url":"https://nyncj.beijing.gov.cn/nyj/snxx/zwyw/326150577/index.html"},"web-8c0843154f49006b":{"name":"《优化营商环境条例》","url":"https://www.samr.gov.cn/djzcj/zcfg/fg/art/2023/art_2a090a379b804089992aa8a24b3b0757.html"},"web-3b9e64a0cdbc3943":{"name":"《海南省创一流营商环境行动计划（2020－2021年）》","url":"https://policy.mofcom.gov.cn/claw/clawContent.shtml?id=91920"}},"topics":[],"units":{"k-92052a1e0611bc45":[["江苏 2024 B类 行测#2"]]}};
